function validate([strength, k]) {
  if (strength.length < 1 || strength.length > 8) return 'strength needs 1 to 8 locks.';
  if (strength.some(v => v < 1 || v > 1000000)) return 'Each strength is between 1 and 10^6.';
  if (k < 1 || k > 10) return 'k is between 1 and 10.';
  return null;
}

