function findMinimumTime(strength, k) {
  const n = strength.length;
  const used = new Array(n).fill(false);
  let best = Infinity;

  function search(broken, time) {
    if (time >= best) return;
    if (broken === n) {
      best = time;
      return;
    }
    const factor = 1 + broken * k;
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      used[i] = true;
      search(broken + 1, time + Math.ceil(strength[i] / factor));
      used[i] = false;
    }
  }

  search(0, 0);
  return best;
}

