function findMinimumTime(strength, k) {
  // Bitmask DP: dp[mask] is the least time to break exactly the locks in mask, in some order.
  const n = strength.length;
  const dp = new Array(1 << n).fill(Infinity);
  dp[0] = 0;
  for (let mask = 0; mask < (1 << n); mask++) {
    let done = 0;
    for (let j = 0; j < n; j++) if (mask & (1 << j)) done++;
    const x = 1 + done * k;
    for (let j = 0; j < n; j++) {
      if (mask & (1 << j)) continue;
      const minutes = Math.floor((strength[j] + x - 1) / x);
      dp[mask | (1 << j)] = Math.min(dp[mask | (1 << j)], dp[mask] + minutes);
    }
  }
  return dp[(1 << n) - 1];
}

