function generate(rand, size) {
  const large = size === 'large';
  const n = large ? 8 : 1 + Math.floor(rand() * 6);
  const k = 1 + Math.floor(rand() * 10);
  // Small strengths make rounding up matter; large ones test the full range.
  const top = rand() < 0.5 ? 1000000 : large ? 1000 : 40;
  const strength = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [strength, k];
}
